import base64
import hashlib
import lzma
from pathlib import Path

EXPECTED_SHA256 = '1f661234e0009884802200ffbbef8e0b4529b580e729f412bb745004de2582b3'
payload = (
''
)
data = lzma.decompress(base64.b64decode(payload))
actual = hashlib.sha256(data).hexdigest()
assert actual == EXPECTED_SHA256, f'SHA mismatch: {actual}'
out = Path('/tmp/test_seed_acessorios_atlas_392.sql')
out.write_bytes(data)
print(out, len(data), actual)
